use super::*;
use serde_json::json;

/// Serializes the one test that mutates the process-wide `$BSC_UI_WRITER` env (env is global to the
/// test binary), so a parallel read never sees a half-set value.
static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[test]
fn read_rev_treats_a_missing_or_odd_rev_as_zero_and_reads_a_real_one() {
    // Backward-compat: a legacy record with no `rev` (and null / non-integer / string values) all
    // read as rev 0, so an old record slots into the concurrency scheme as "never revised".
    assert_eq!(read_rev(&json!({ "id": "x", "name": "X" })), 0, "absent ⇒ 0");
    assert_eq!(read_rev(&json!({ "id": "x", "rev": null })), 0, "null ⇒ 0");
    assert_eq!(read_rev(&json!({ "id": "x", "rev": "7" })), 0, "string ⇒ 0");
    assert_eq!(read_rev(&json!({ "id": "x", "rev": 1.5 })), 0, "non-integer ⇒ 0");
    // A real integer rev reads through.
    assert_eq!(read_rev(&json!({ "id": "x", "rev": 4 })), 4);
}

#[test]
fn stamp_bumps_rev_sets_time_and_writer_and_preserves_other_fields() {
    // A brand-new record (prior 0) → rev 1, plus the two stamps; the original fields survive.
    let mut rec = json!({ "id": "button", "name": "Button", "kitId": "react-ui" });
    stamp(&mut rec, 0, "alice", "2026-07-16T00:00:00Z");
    assert_eq!(rec["rev"], json!(1), "a fresh record's first write is rev 1");
    assert_eq!(rec["updatedAt"], "2026-07-16T00:00:00Z");
    assert_eq!(rec["updatedBy"], "alice");
    assert_eq!(rec["id"], "button", "the id is untouched");
    assert_eq!(rec["name"], "Button", "domain fields are preserved");
    assert_eq!(rec["kitId"], "react-ui");

    // The next write bumps from the (now current) rev, and a stale `rev` field on the incoming
    // value is OVERWRITTEN by prior+1 (the store's rev is authoritative, not the payload's).
    rec["rev"] = json!(99); // pretend the caller sent a stale value
    stamp(&mut rec, 1, "bob", "2026-07-16T00:01:00Z");
    assert_eq!(rec["rev"], json!(2), "bumped from the prior stored rev, not the payload's 99");
    assert_eq!(rec["updatedBy"], "bob");
}

#[test]
fn stamp_is_a_no_op_on_a_non_object() {
    // Defensive: real records are objects, but a non-object never panics.
    let mut arr = json!([1, 2, 3]);
    stamp(&mut arr, 0, "x", "t");
    assert_eq!(arr, json!([1, 2, 3]));
}

#[test]
fn log_value_reports_the_current_stamp_and_defaults_for_a_legacy_record() {
    // A legacy record (no stamps) logs as rev 0 with empty attribution and an empty history.
    let legacy = json!({ "id": "old", "name": "Old" });
    assert_eq!(
        log_value("old", &legacy),
        json!({ "id": "old", "rev": 0, "updatedAt": "", "updatedBy": "", "history": [] }),
    );
    // A stamped record surfaces all three (still an empty history — it was never written via
    // `stamp_with_history`, only the bare `stamp`).
    let mut rec = json!({ "id": "card", "name": "Card" });
    stamp(&mut rec, 2, "designer", "2026-07-16T09:00:00Z");
    assert_eq!(
        log_value("card", &rec),
        json!({ "id": "card", "rev": 3, "updatedAt": "2026-07-16T09:00:00Z", "updatedBy": "designer", "history": [] }),
    );
}

#[test]
fn merge_over_preserves_every_field_the_write_did_not_restate() {
    // #4197 / #4154: the write is ADDITIVE. A worker told to edit the RECORD of a component whose
    // file is generated (#4193) sends only what it changed; nothing else may move.
    let prior = json!({
        "id": "fleetpage", "name": "FleetPage", "kitId": "base-studio-code", "role": "page",
        "composes": ["Row", "Card"], "src": "src/features/planner/fleet/Fleet.tsx", "srcText": "old",
        "rev": 4, "updatedAt": "2026-07-01T00:00:00Z", "updatedBy": "designer", "history": [{ "rev": 4 }],
    });
    let merged = merge_over(&prior, &json!({ "id": "fleetpage", "srcText": "new" }), &[]);
    assert_eq!(merged["srcText"], "new", "the supplied field is overlaid");
    assert_eq!(merged["kitId"], "base-studio-code");
    assert_eq!(merged["role"], "page");
    assert_eq!(merged["composes"], json!(["Row", "Card"]));
    assert_eq!(merged["src"], "src/features/planner/fleet/Fleet.tsx");
    // The server-managed fields ride through untouched here — `stamp_with_history` re-writes them
    // right after, so the merge needs no special case for them.
    assert_eq!(merged["rev"], json!(4));
}

#[test]
fn merge_over_removes_a_field_only_when_asked_by_null_or_clear() {
    let prior = json!({ "id": "card", "name": "Card", "folder": "shared/ui", "src": "Card.tsx" });
    // A JSON `null` value is a deletion, not a stored null (the `set_impl` spelling, #4154)…
    let nulled = merge_over(&prior, &json!({ "id": "card", "folder": null }), &[]);
    assert!(nulled.get("folder").is_none(), "null removes rather than stores null");
    assert_eq!(nulled["src"], "Card.tsx", "its neighbours are untouched");
    // …and `--clear a,b` is the flag form of the same thing.
    let cleared = merge_over(&prior, &json!({ "id": "card" }), &["folder".into(), "src".into()]);
    assert!(cleared.get("folder").is_none() && cleared.get("src").is_none());
    assert_eq!(cleared["name"], "Card");
    // `--clear` is applied LAST, so it beats a value the same write supplied.
    let contradictory = merge_over(&prior, &json!({ "id": "card", "folder": "new" }), &["folder".into()]);
    assert!(contradictory.get("folder").is_none(), "--clear wins over a supplied value");
    // A blank clear list changes nothing.
    assert_eq!(merge_over(&prior, &json!({ "id": "card" }), &[]), prior);
}

#[test]
fn merge_over_never_removes_the_id_and_falls_back_on_a_non_object() {
    // `id` is the store key: a record that lost it is unreadable by list/get/doctor, so neither
    // spelling of a removal may take it.
    let prior = json!({ "id": "card", "name": "Card" });
    assert_eq!(merge_over(&prior, &json!({ "id": null, "name": "C2" }), &[])["id"], "card");
    assert_eq!(merge_over(&prior, &json!({ "id": "card" }), &["id".into()])["id"], "card");
    // A CREATE (no prior) is the incoming record verbatim — there is nothing to preserve…
    let fresh = json!({ "id": "new", "name": "New" });
    assert_eq!(merge_over(&Value::Null, &fresh, &[]), fresh);
    // …and a non-object on either side cannot be merged field-wise, so the incoming value wins
    // (the honest fallback, rather than silently keeping a malformed record).
    assert_eq!(merge_over(&json!([1, 2]), &fresh, &[]), fresh);
    assert_eq!(merge_over(&prior, &json!("nope"), &[]), json!("nope"));
}

#[test]
fn changed_fields_reports_created_then_the_diffed_top_level_fields() {
    // A brand-new record (prior absent, rev 0) is summarized as "created", not a field-by-field diff.
    let fresh = json!({ "id": "button", "name": "Button", "kitId": "react-ui" });
    assert_eq!(changed_fields(&Value::Null, &fresh), vec!["created".to_string()]);
    assert_eq!(changed_fields(&json!({}), &fresh), vec!["created".to_string()]);

    // A real edit diffs the top-level fields: a changed value, an added field, and a removed one all
    // count; unchanged fields do not; the result is sorted for a stable entry.
    let prior = json!({ "id": "button", "rev": 3, "name": "Button", "kitId": "react-ui", "old": 1 });
    let next = json!({ "id": "button", "name": "Button", "kitId": "mui", "srcText": "…" });
    assert_eq!(
        changed_fields(&prior, &next),
        vec!["kitId".to_string(), "old".to_string(), "srcText".to_string()],
        "changed kitId + added srcText + removed old; id/name unchanged",
    );

    // The provenance/history fields and the derived `seedHash` never count as an authored change.
    let p2 = json!({ "id": "x", "rev": 2, "name": "X", "seedHash": "aaa" });
    let n2 = json!({ "id": "x", "rev": 3, "updatedAt": "t", "updatedBy": "u", "history": [1], "name": "X", "seedHash": "bbb" });
    assert!(changed_fields(&p2, &n2).is_empty(), "only rev/stamps/history/seedHash moved ⇒ no authored change");
}

#[test]
fn stamp_with_history_appends_a_capped_newest_last_log() {
    // First write on a fresh record: rev 1, one "created" entry carrying the note.
    let mut rec = json!({ "id": "button", "name": "Button" });
    stamp_with_history(&mut rec, &Value::Null, "designer", "2026-07-16T00:00:00Z", Some("initial"));
    assert_eq!(rec["rev"], json!(1));
    let hist = rec["history"].as_array().unwrap();
    assert_eq!(hist.len(), 1);
    assert_eq!(
        hist[0],
        json!({ "rev": 1, "at": "2026-07-16T00:00:00Z", "by": "designer", "note": "initial", "changed": ["created"] }),
    );

    // Second write carries the prior history forward and appends newest-LAST; a blank note is dropped.
    let prior = rec.clone();
    let mut next = json!({ "id": "button", "name": "Button 2" });
    stamp_with_history(&mut next, &prior, "alice", "2026-07-16T00:01:00Z", Some("   "));
    assert_eq!(next["rev"], json!(2));
    let hist = next["history"].as_array().unwrap();
    assert_eq!(hist.len(), 2, "prior entry carried forward + the new one");
    assert_eq!(hist[0]["rev"], json!(1), "oldest stays first (append order)");
    assert_eq!(hist[1], json!({ "rev": 2, "at": "2026-07-16T00:01:00Z", "by": "alice", "changed": ["name"] }), "no note key when blank");

    // The incoming record's own `history` is SERVER-MANAGED — a forged one is discarded.
    let mut forged = json!({ "id": "button", "name": "Button 3", "history": [{ "rev": 999, "by": "attacker" }] });
    stamp_with_history(&mut forged, &next, "bob", "2026-07-16T00:02:00Z", None);
    let hist = forged["history"].as_array().unwrap();
    assert_eq!(hist.len(), 3, "grew from the PRIOR's 2, not the forged 1");
    assert!(hist.iter().all(|e| e["by"] != json!("attacker")), "the forged entry is gone");
}

/// Write `srcText` `n` times, returning the final record — the fixture the revert tests share.
fn write_sources(sources: &[&str]) -> Value {
    let mut rec = Value::Null;
    let mut prior = Value::Null;
    for (i, s) in sources.iter().enumerate() {
        rec = json!({ "id": "graphprimitive", "srcText": s });
        stamp_with_history(&mut rec, &prior, "designer", &format!("2026-08-14T00:0{i}:00Z"), None);
        prior = rec.clone();
    }
    rec
}

#[test]
fn a_write_retains_the_source_it_replaced_so_it_can_be_reverted() {
    // THE incident, in miniature: `bsc ui log` recorded that `srcText` changed and never what it was,
    // so a bad designer write on a record with no packaged seed was unrecoverable.
    let rec = write_sources(&["good", "broken"]);
    let hist = rec["history"].as_array().unwrap();
    assert!(hist[0].get("prevSrc").is_none(), "a CREATE replaced nothing: {}", hist[0]);
    assert_eq!(hist[1]["prevSrc"], "good", "the write that broke it carries the version it broke");
    assert_eq!(src_at_rev(&rec, 1).as_deref(), Some("good"), "rev 1's source is reachable");
    assert_eq!(revertible_revs(&rec), vec![1]);
}

#[test]
fn an_unchanged_source_stores_no_duplicate_and_a_revert_reads_through_it() {
    // A metadata-only write must not store a second copy of an identical source — that is the whole
    // reason `prevSrc` is conditional. But it must also not BLOCK the rung: reverting to rev 2 (whose
    // own write never touched the source) still has to find the bytes rev 2 actually held.
    let mut rec = write_sources(&["good"]);
    let prior = rec.clone();
    let mut meta = json!({ "id": "graphprimitive", "srcText": "good", "folder": "shared/ui/spec" });
    stamp_with_history(&mut meta, &prior, "refolder", "2026-08-14T00:01:00Z", None);
    rec = meta;
    let prior = rec.clone();
    let mut broken = json!({ "id": "graphprimitive", "srcText": "broken", "folder": "shared/ui/spec" });
    stamp_with_history(&mut broken, &prior, "designer", "2026-08-14T00:02:00Z", None);

    let hist = broken["history"].as_array().unwrap();
    assert!(hist[1].get("prevSrc").is_none(), "the metadata write stored no duplicate: {}", hist[1]);
    assert_eq!(hist[2]["prevSrc"], "good");
    // Both revs land on the same bytes — which is correct, because both revs HELD the same bytes.
    assert_eq!(src_at_rev(&broken, 2).as_deref(), Some("good"), "rev 2 reads through the metadata write");
    assert_eq!(src_at_rev(&broken, 1).as_deref(), Some("good"));
}

#[test]
fn a_write_that_deletes_the_source_entirely_is_still_revertible() {
    // `--replace` (and `--clear srcText`) can drop the field outright. `dropped` names it; without a
    // retained copy the record's only source would be gone, which is the unrecoverable case itself.
    let prior = write_sources(&["good"]);
    let mut gone = json!({ "id": "graphprimitive" });
    stamp_with_history(&mut gone, &prior, "replace", "2026-08-14T01:00:00Z", None);
    let last = gone["history"].as_array().unwrap().last().unwrap();
    assert_eq!(last["dropped"], json!(["srcText"]), "the removal stays legible");
    assert_eq!(last["prevSrc"], "good", "...and the bytes survive it");
    assert_eq!(src_at_rev(&gone, 1).as_deref(), Some("good"));
}

#[test]
fn only_the_most_recent_prev_src_cap_entries_retain_their_source() {
    // srcText is 77.6% of a record's payload, so the CONTENT is capped far below the METADATA. Past
    // the cap a revert must report that it cannot reach, not silently land on the wrong revision.
    let sources: Vec<String> = (0..(PREV_SRC_CAP + 4)).map(|i| format!("v{i}")).collect();
    let rec = write_sources(&sources.iter().map(String::as_str).collect::<Vec<_>>());
    let hist = rec["history"].as_array().unwrap();
    let retained = hist.iter().filter(|e| e.get("prevSrc").is_some()).count();
    assert_eq!(retained, PREV_SRC_CAP, "content is capped at PREV_SRC_CAP");
    assert_eq!(hist.len(), sources.len(), "...while the METADATA log keeps every entry");

    let reachable = revertible_revs(&rec);
    assert_eq!(reachable.len(), PREV_SRC_CAP);
    let newest = *reachable.last().unwrap();
    assert_eq!(src_at_rev(&rec, newest).as_deref(), Some(sources[newest as usize - 1].as_str()));
    // One rung below the oldest retained one is out of reach — and says so rather than guessing.
    assert_eq!(src_at_rev(&rec, reachable[0] - 1), None, "aged-out revisions report unreachable");
}

#[test]
fn src_at_rev_is_none_when_there_is_nothing_to_go_back_to() {
    assert_eq!(src_at_rev(&json!({ "id": "x" }), 1), None, "no history at all");
    let fresh = write_sources(&["only"]);
    assert_eq!(src_at_rev(&fresh, 1), None, "a record written once has no earlier source");
    assert!(revertible_revs(&fresh).is_empty());
}

#[test]
fn stamp_with_history_caps_at_history_cap_dropping_the_oldest() {
    let mut rec = json!({ "id": "x", "name": "n0" });
    let mut prior = Value::Null;
    // Write HISTORY_CAP + 5 times; the log must retain exactly the most recent HISTORY_CAP.
    for i in 0..(HISTORY_CAP + 5) {
        rec = json!({ "id": "x", "name": format!("n{i}") });
        stamp_with_history(&mut rec, &prior, "w", "2026-07-16T00:00:00Z", None);
        prior = rec.clone();
    }
    let hist = rec["history"].as_array().unwrap();
    assert_eq!(hist.len(), HISTORY_CAP, "capped");
    let oldest_rev = hist[0]["rev"].as_i64().unwrap();
    let newest_rev = hist[hist.len() - 1]["rev"].as_i64().unwrap();
    assert_eq!(newest_rev, (HISTORY_CAP + 5) as i64, "the last write's rev is retained");
    assert_eq!(oldest_rev, newest_rev - (HISTORY_CAP as i64) + 1, "exactly the most recent CAP, oldest dropped");
}

#[test]
fn log_value_reverses_history_to_newest_first() {
    let mut rec = json!({ "id": "x", "name": "a" });
    stamp_with_history(&mut rec, &Value::Null, "w", "2026-07-16T00:00:00Z", None);
    let prior = rec.clone();
    let mut next = json!({ "id": "x", "name": "b" });
    stamp_with_history(&mut next, &prior, "w", "2026-07-16T00:01:00Z", None);
    // Stored oldest-first (rev 1 then rev 2); the LOG must read newest-first (rev 2 then rev 1).
    let logged = log_value("x", &next);
    let hist = logged["history"].as_array().unwrap();
    assert_eq!(hist[0]["rev"], json!(2), "newest first");
    assert_eq!(hist[1]["rev"], json!(1));
}

#[test]
fn resolve_writer_precedence_explicit_then_env_then_unknown() {
    let _guard = ENV_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    // Explicit `--by` wins regardless of the env.
    std::env::set_var("BSC_UI_WRITER", "ci-bot");
    assert_eq!(resolve_writer(Some("alice")), "alice");
    // A blank explicit falls through to the env.
    assert_eq!(resolve_writer(Some("   ")), "ci-bot");
    assert_eq!(resolve_writer(None), "ci-bot");
    // With no env (and no/blank explicit) the default is "unknown".
    std::env::remove_var("BSC_UI_WRITER");
    assert_eq!(resolve_writer(None), "unknown");
    assert_eq!(resolve_writer(Some("")), "unknown");
    assert_eq!(resolve_writer(Some("designer")), "designer");
}

#[test]
fn now_iso_is_a_well_formed_utc_stamp() {
    let ts = now_iso();
    // `YYYY-MM-DDTHH:MM:SSZ` — 20 chars, ends in Z, and round-trips back through the inverse.
    assert_eq!(ts.len(), 20, "ISO-8601 second-resolution: {ts}");
    assert!(ts.ends_with('Z'), "UTC 'Z' suffix: {ts}");
