/// The stored entry both data-loss requests destroyed: a real carried test whose `src/` file no longer
/// exists, so the record is the ONLY copy of those assertions.
fn carried(name: &str, bytes: usize) -> Value {
    serde_json::json!({ "name": name, "src": "x".repeat(bytes), "ext": ".ts" })
}

#[test]
fn upsert_test_appends_a_new_name_and_keeps_every_sibling() {
    let before = Value::Array(vec![carried("Tabstrip rendering", 12_293)]);
    let after = upsert_test(Some(&before), carried("next tab name", 1_513));
    let arr = after.as_array().expect("an array");
    assert_eq!(arr.len(), 2, "the sibling survives: {after}");
    assert_eq!(arr[0]["name"], "Tabstrip rendering");
    assert_eq!(arr[0]["src"].as_str().unwrap().len(), 12_293, "and survives WHOLE");
    assert_eq!(arr[1]["name"], "next tab name");
}

#[test]
fn upsert_test_replaces_the_same_name_in_place_rather_than_appending_a_twin() {
    let before = Value::Array(vec![carried("a", 10), carried("b", 20)]);
    let after = upsert_test(Some(&before), carried("a", 30));
    let arr = after.as_array().unwrap();
    assert_eq!(arr.len(), 2, "a re-pair is not a second entry");
    assert_eq!(arr[0]["name"], "a", "and keeps its POSITION");
    assert_eq!(arr[0]["src"].as_str().unwrap().len(), 30);
    assert_eq!(arr[1]["name"], "b");
}

