#[test]
fn lost_tests_names_a_dropped_entry_by_name_and_byte_length() {
    // Request #221, verbatim: the store held ONLY the new 1,513-byte entry afterwards.
    let before = Value::Array(vec![carried("Tabstrip rendering", 12_293)]);
    let after = Value::Array(vec![carried("next tab name", 1_513)]);
    let lost = lost_tests(Some(&before), Some(&after));
    assert_eq!(
