#[test]
fn lost_tests_sees_a_truncation_an_entry_count_cannot() {
    // THE CENTREPIECE. Both real losses replaced a one-entry array with a one-entry array, so a guard
    // that counted entries reported "1 before, 1 after — fine" while a 27,648-byte body became 1,513.
    let before = Value::Array(vec![carried("seed hash (#2483)", 27_648)]);
    let after = Value::Array(vec![carried("seed hash (#2483)", 1_513)]);
    assert_eq!(
        before.as_array().map(Vec::len),
        after.as_array().map(Vec::len),
        "the counts AGREE — which is exactly why counting cannot see this",
    );
    let lost = lost_tests(Some(&before), Some(&after));
    assert_eq!(
        lost,
        vec![TestLoss { name: "seed hash (#2483)".into(), was: 27_648, now: Some(1_513) }],
    );
}

#[test]
fn lost_tests_is_empty_for_an_upsert_and_for_a_record_that_carried_none() {
    let before = Value::Array(vec![carried("a", 100)]);
    let after = upsert_test(Some(&before), carried("b", 5));
    assert!(lost_tests(Some(&before), Some(&after)).is_empty(), "an upsert loses nothing");
    // A GROWING entry is not a loss.
    let grown = upsert_test(Some(&before), carried("a", 200));
    assert!(lost_tests(Some(&before), Some(&grown)).is_empty());
    // Nothing stored ⇒ nothing to lose, whatever is written.
    assert!(lost_tests(None, Some(&after)).is_empty());
    // An entry that carried no bytes has nothing to lose either.
    let empty = Value::Array(vec![serde_json::json!({ "name": "placeholder", "src": "" })]);
    assert!(lost_tests(Some(&empty), Some(&Value::Array(vec![]))).is_empty());
}

#[test]
fn guard_no_test_loss_refuses_loudly_and_names_the_record() {
    let before = Value::Array(vec![carried("seed hash (#2483)", 27_648)]);
    let ok = upsert_test(Some(&before), carried("seed refresh", 1_200));
    assert_eq!(
        guard_no_test_loss("seed-refresh.ts", Some(&before), Some(&ok), &["seed refresh"]),
        Ok(vec![]),
        "an upsert loses nothing and has nothing to report",
    );

    // REQUEST #220, verbatim: the new entry REPLACED the array, taking a test this write never named.
    let replaced = Value::Array(vec![carried("seed refresh", 1_200)]);
    let err = guard_no_test_loss("seed-refresh.ts", Some(&before), Some(&replaced), &["seed refresh"])
        .unwrap_err();
    assert!(err.contains("seed-refresh.ts"), "names the record: {err}");
    assert!(err.contains("seed hash (#2483)"), "names the entry: {err}");
    assert!(err.contains("27648"), "and the bytes at stake: {err}");
}

#[test]
fn guard_no_test_loss_reports_rather_than_refuses_a_shrink_of_the_test_it_is_writing() {
    // A re-pair against a file that genuinely got shorter is the CALLER'S OWN EDIT. Refusing it would
    // make `tests set` unable to update a test at all — so it is returned, and the verb says so. The
    // property the guard defends is that a truncation is never SILENT, not that it never happens.
    let before = Value::Array(vec![carried("a", 27_648), carried("b", 100)]);
    let after = upsert_test(Some(&before), carried("a", 1_513));
    let reported = guard_no_test_loss("x.ts", Some(&before), Some(&after), &["a"])
        .expect("the write this caller asked for is allowed");
    assert_eq!(reported, vec![TestLoss { name: "a".into(), was: 27_648, now: Some(1_513) }]);
    // …and the sibling it never named is untouched, which is the half that is refused.
    assert!(after.as_array().unwrap().iter().any(|t| t["name"] == "b"));
}

#[test]
fn test_entry_carries_the_real_extension_and_omits_one_the_emitter_cannot_model() {
    let e = test_entry(std::path::Path::new("/x/useNav.test.tsx"), "useNav", "const a = 1;\n");
    assert_eq!(e["ext"], ".tsx", "the writer READ the file, so it never leaves the emitter to guess");
    assert_eq!(e["name"], "useNav");
    assert_eq!(e["src"], "const a = 1;\n");
    // A Rust test file has no emitter `ext` — absent is honest, a wrong one is not.
    let r = test_entry(std::path::Path::new("/x/seeded.test.rs"), "seeded", "#[test] fn t() {}");
    assert!(r.get("ext").is_none(), "{r}");
}
